package me.kright.gametools.pga2d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer


/**
 * A rotor: rotation around the center of coordinates, applied with rotor.sandwich(obj).
 * The fields s and xy hold the cosine and sine of the half-angle. The 2d analog of Pga3dRotor;
 * a rotor is the exponent of a grade-2 element concentrated at the origin (the xy blade).
 *
 * Variable fields: s, xy.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga2d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga2dRotor(s: Double = 0.0,
                            xy: Double = 0.0) derives CanEqual, FlatDoubleSerializer:

  override def toString: String =
    s"Pga2dRotor(s = $s, xy = $xy)"

  def dual: Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = xy,
      x = 0.0,
      y = 0.0,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = s,
    )

  def bulk: Pga2dRotor =
    this

  @targetName("unaryMinus")
  def unary_- : Pga2dRotor =
    Pga2dRotor(
      s = -s,
      xy = -xy,
    )

  def reverse: Pga2dRotor =
    Pga2dRotor(
      s = s,
      xy = -xy,
    )

  def antiReverse: Pga2dRotor =
    Pga2dRotor(
      s = -s,
      xy = xy,
    )

  def bulkNormSquare: Double =
    (s * s + xy * xy)

  def bulkNorm: Double =
    Math.sqrt(bulkNormSquare)

  def normalizedByBulk =
    this / bulkNorm

  def normSquare: Double =
    (s * s + xy * xy)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga2dRotor =
    Pga2dRotor(
      s = r * s,
      xy = r * xy,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga2dRotor =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga2dRotor): Pga2dRotor =
    Pga2dRotor(
      s = (r.s + s),
      xy = (r.xy + xy),
    )

  @targetName("minus")
  def -(r: Pga2dRotor): Pga2dRotor =
    Pga2dRotor(
      s = (s - r.s),
      xy = (xy - r.xy),
    )

  def madd(r: Pga2dRotor, mult: Double): Pga2dRotor =
    Pga2dRotor(
      s = (s + mult * r.s),
      xy = (xy + mult * r.xy),
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga2dRotor): Pga2dRotor =
    Pga2dRotor(
      s = s * r.s,
      xy = xy * r.xy,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga2dRotor =
    Pga2dRotor(
      s = 1.0 / s,
      xy = 1.0 / xy,
    )

  /**
   * The xy coefficient of the rotation generator, i.e. the half-angle of the rotation.
   * There is no single-blade grade-2 class in 2d, so the coefficient is returned as a
   * plain Double; Pga2dRotor.exp is the inverse. Scale-invariant via atan2.
   */
  def log(): Double =
    if (s < 0.0) Math.atan2(-xy, -s)
    else Math.atan2(xy, s)

  /**
   * Spherical linear interpolation along the geodesic from this (t = 0) to b (t = 1),
   * with constant angular velocity. Computes this * (this.reverse.geometric(b))^t via log/exp.
   * Assumes both this and b are normalized; the result is normalized.
   * Near-antipodal inputs (b close to -this) are ill-conditioned: the geodesic is undefined
   * there and the interpolation direction becomes numerically unstable.
   */
  def slerp(b: Pga2dRotor, t: Double): Pga2dRotor =
    this.geometric(Pga2dRotor.exp(this.reverse.geometric(b).log() * t))

  /**
   * Normalized linear interpolation: the componentwise lerp this * (1 - t) + b * t, renormalized.
   * A fast APPROXIMATION of slerp: the angular velocity is not constant, so intermediate values
   * deviate from the true geodesic. The error is negligible for small angles between this and b
   * and grows toward the midpoint of large rotations. Assumes both inputs are normalized.
   */
  def nlerp(b: Pga2dRotor, t: Double): Pga2dRotor =
    (this * (1.0 - t) + b * t).normalizedByNorm

  def toMultivector: Pga2dMultivector =
    Pga2dMultivector(
      s = s,
      w = 0.0,
      x = 0.0,
      y = 0.0,
      wx = 0.0,
      wy = 0.0,
      xy = xy,
      i = 0.0,
    )

  def toMotor: Pga2dMotor =
    Pga2dMotor(
      s = s,
      wx = 0.0,
      wy = 0.0,
      xy = xy,
    )

  def toProjectivePointUnsafe: Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = 0.0,
      y = 0.0,
      w = xy,
    )

  def toProjectiveTranslatorUnsafe: Pga2dProjectiveTranslator =
    Pga2dProjectiveTranslator(
      s = s,
      wx = 0.0,
      wy = 0.0,
    )

  def axisX: Pga2dVector =
    Pga2dVector(
      x = (s * s - xy * xy),
      y = -2.0 * s * xy,
    )

  def axisY: Pga2dVector =
    Pga2dVector(
      x = 2.0 * s * xy,
      y = (s * s - xy * xy),
    )

  infix def geometric(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = (r.s * s - r.xy * xy),
      wx = (r.wx * s + r.wy * xy),
      wy = (r.wy * s - r.wx * xy),
      xy = (r.s * xy + r.xy * s),
    )

  infix def geometric(r: Pga2dLine): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = r.w * s,
      x = (r.x * s + r.y * xy),
      y = (r.y * s - r.x * xy),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = r.w * xy,
    )

  infix def geometric(r: Pga2dProjectivePoint): Pga2dMotor =
