      s = r.s * (sMs + xyMxy),
      wx = (r.wx * (sMs - xyMxy) + 2.0 * r.wy * sMxy),
      wy = (r.wy * (sMs - xyMxy) - 2.0 * r.wx * sMxy),
      xy = r.xy * (sMs + xyMxy),
