      s = r.s * (sMs + xyMxy),
      wx = (r.wx * (sMs - xyMxy) + 2.0 * r.wy * sMxy),
      wy = (r.wy * (sMs - xyMxy) - 2.0 * r.wx * sMxy),
    )

  infix def sandwich(r: Pga2dTranslator): Pga2dProjectiveTranslator =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dProjectiveTranslator(
      s = (sMs + xyMxy),
      wx = (r.wx * (sMs - xyMxy) + 2.0 * r.wy * sMxy),
      wy = (r.wy * (sMs - xyMxy) - 2.0 * r.wx * sMxy),
    )

  infix def sandwich(r: Pga2dVector): Pga2dVector =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dVector(
      x = (r.x * (sMs - xyMxy) + 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) - 2.0 * r.x * sMxy),
    )

  infix def sandwich(r: Pga2dPoint): Pga2dProjectivePoint =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dProjectivePoint(
      x = (r.x * (sMs - xyMxy) + 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) - 2.0 * r.x * sMxy),
      w = (sMs + xyMxy),
    )

  infix def sandwich(r: Pga2dLineCentral): Pga2dLineCentral =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dLineCentral(
      x = (r.x * (sMs - xyMxy) + 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) - 2.0 * r.x * sMxy),
    )

  infix def sandwich(r: Pga2dPseudoScalar): Pga2dPseudoScalar =
    Pga2dPseudoScalar(
      i = r.i * (s * s + xy * xy),
    )

  infix def sandwich(r: Pga2dPointCenter.type): Pga2dRotor =
    Pga2dRotor(
      s = 0.0,
      xy = (s * s + xy * xy),
    )

  infix def reverseSandwich(r: Pga2dMotor): Pga2dMotor =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dMotor(
      s = r.s * (sMs + xyMxy),
      wx = (r.wx * (sMs - xyMxy) - 2.0 * r.wy * sMxy),
      wy = (r.wy * (sMs - xyMxy) + 2.0 * r.wx * sMxy),
      xy = r.xy * (sMs + xyMxy),
    )

  infix def reverseSandwich(r: Pga2dLine): Pga2dLine =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dLine(
      x = (r.x * (sMs - xyMxy) - 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) + 2.0 * r.x * sMxy),
      w = r.w * (sMs + xyMxy),
    )

  infix def reverseSandwich(r: Pga2dProjectivePoint): Pga2dProjectivePoint =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dProjectivePoint(
      x = (r.x * (sMs - xyMxy) - 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) + 2.0 * r.x * sMxy),
      w = r.w * (sMs + xyMxy),
    )

  infix def reverseSandwich(r: Pga2dRotor): Pga2dRotor =
    val sMs = s * s
    val xyMxy = xy * xy
    Pga2dRotor(
      s = r.s * (sMs + xyMxy),
      xy = r.xy * (sMs + xyMxy),
    )

  infix def reverseSandwich(r: Pga2dProjectiveTranslator): Pga2dProjectiveTranslator =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dProjectiveTranslator(
      s = r.s * (sMs + xyMxy),
      wx = (r.wx * (sMs - xyMxy) - 2.0 * r.wy * sMxy),
      wy = (r.wy * (sMs - xyMxy) + 2.0 * r.wx * sMxy),
    )

  infix def reverseSandwich(r: Pga2dTranslator): Pga2dProjectiveTranslator =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dProjectiveTranslator(
      s = (sMs + xyMxy),
      wx = (r.wx * (sMs - xyMxy) - 2.0 * r.wy * sMxy),
      wy = (r.wy * (sMs - xyMxy) + 2.0 * r.wx * sMxy),
    )

  infix def reverseSandwich(r: Pga2dVector): Pga2dVector =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dVector(
      x = (r.x * (sMs - xyMxy) - 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) + 2.0 * r.x * sMxy),
    )

  infix def reverseSandwich(r: Pga2dPoint): Pga2dProjectivePoint =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dProjectivePoint(
      x = (r.x * (sMs - xyMxy) - 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) + 2.0 * r.x * sMxy),
      w = (sMs + xyMxy),
    )

  infix def reverseSandwich(r: Pga2dLineCentral): Pga2dLineCentral =
    val sMs = s * s
    val sMxy = s * xy
    val xyMxy = xy * xy
    Pga2dLineCentral(
      x = (r.x * (sMs - xyMxy) - 2.0 * r.y * sMxy),
      y = (r.y * (sMs - xyMxy) + 2.0 * r.x * sMxy),
    )

  infix def reverseSandwich(r: Pga2dPseudoScalar): Pga2dPseudoScalar =
    Pga2dPseudoScalar(
      i = r.i * (s * s + xy * xy),
    )

  infix def reverseSandwich(r: Pga2dPointCenter.type): Pga2dRotor =
    Pga2dRotor(
      s = 0.0,
      xy = (s * s + xy * xy),
    )

  infix def cross(r: Pga2dMotor): Pga2dVector =
    Pga2dVector(
      x = r.wx * xy,
      y = r.wy * xy,
    )

  infix def cross(r: Pga2dLine): Pga2dLineCentral =
    Pga2dLineCentral(
      x = r.y * xy,
      y = -r.x * xy,
    )

  infix def cross(r: Pga2dProjectivePoint): Pga2dVector =
    Pga2dVector(
      x = r.y * xy,
      y = -r.x * xy,
    )

  infix def cross(r: Pga2dProjectiveTranslator): Pga2dVector =
    Pga2dVector(
      x = r.wx * xy,
      y = r.wy * xy,
    )

  infix def cross(r: Pga2dTranslator): Pga2dVector =
    Pga2dVector(
      x = r.wx * xy,
      y = r.wy * xy,
    )

  infix def cross(r: Pga2dVector): Pga2dVector =
    Pga2dVector(
      x = r.y * xy,
      y = -r.x * xy,
    )

  infix def cross(r: Pga2dPoint): Pga2dVector =
    Pga2dVector(
      x = r.y * xy,
      y = -r.x * xy,
    )

  infix def cross(r: Pga2dLineCentral): Pga2dLineCentral =
    Pga2dLineCentral(
      x = r.y * xy,
      y = -r.x * xy,
    )


object Pga2dRotor:

  inline val componentsCount = 2

  val id: Pga2dRotor = Pga2dRotor(1.0, 0.0)

  /** exp of the rotation generator xy (the half-angle of the rotation): the inverse of rotor.log() */
  def exp(xy: Double): Pga2dRotor =
    Pga2dRotor(Math.cos(xy), Math.sin(xy))

  def rotation(from: Pga2dLineCentral, to: Pga2dLineCentral): Pga2dRotor = {
    // not Math.sqrt(from.normSquare * to.normSquare): the product overflows/underflows
    // for extreme magnitudes (~1e100 or ~1e-100) where each norm alone is still fine
    val norm = from.norm * to.norm
    val r2a = to.geometric(from) / norm
    val dot = r2a.s

    // the -0.9 threshold keeps (1.0 + dot) >= 0.1, so the half-angle branch loses
    // at most ~2e-15 relative to the dot rounding; angles closer to pi take the
    // exact-wedge branch below, which stays ~1e-15 all the way to pi
    if (dot > -0.9) {
      val newCos = Math.sqrt((1.0 + dot) / 2.0)
      val newSinDivSin2 = 0.5 / newCos
      return Pga2dRotor(newCos, r2a.xy * newSinDivSin2)
    }

    // nearly a rotation by pi, the full angle is pi - eps. The wedge r2a.xy cancels
    // catastrophically near pi (~1e-17 absolute noise), so it is recomputed with
    // error-free products; the dot guard bounds |wedge| <= sin(acos(0.9)) ~ 0.44,
    // where asin is well-conditioned - unlike atan2 near pi, whose ~ulp(pi)
    // absolute error would be ~1e-16/eps relative in s.
    // Exactly antipodal inputs (wedge == 0) give the exact pi rotor (0, 1)
    import me.kright.gametools.mathutil.ExactArith.diffOfProducts
    val wedge = diffOfProducts(from.y, to.x, from.x, to.y) / norm
    val eps = Math.asin(Math.abs(wedge))
    val xy = if (wedge < 0.0) -Math.cos(eps * 0.5) else Math.cos(eps * 0.5)
    Pga2dRotor(Math.sin(eps * 0.5), xy)
  }

  def rotation(from: Pga2dVector, to: Pga2dVector): Pga2dRotor =
    rotation(from.dual, to.dual)

  /** restore rotor from a rotated orthonormal basis (columns of a 2x2 rotation matrix),
   *  so that restored.sandwich(Pga2dVector(1, 0)) == axisX and restored.sandwich(Pga2dVector(0, 1)) == axisY.
   *  axisY is redundant in 2d (SO(2) has one degree of freedom), it is used only to symmetrize rounding errors,
   *  in the same way as Pga3dRotor.restore uses (m01 - m10) */
  def restore(axisX: Pga2dVector, axisY: Pga2dVector): Pga2dRotor = {
    val cosT = 0.5 * (axisX.x + axisY.y)
    val sinT = 0.5 * (axisY.x - axisX.y)
    // both branches give the same rotor; -0.9 is not a correctness boundary, it only picks
    // the better-conditioned half-angle form: (1 + cosT) loses precision near the angle pi
    if (cosT > -0.9) Pga2dRotor(1.0 + cosT, sinT).normalizedByNorm
    else Pga2dRotor(sinT, 1.0 - cosT).normalizedByNorm
  }